import{z as o,x as m,o as E,c as d,q as i,j as I,D as t,d as l,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"NILS 与 ILS","description":"","frontmatter":{"title":"NILS 与 ILS","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/nils-ils.md","filePath":"litho/nils-ils.md","lastUpdated":1791413859000}'),B={name:"litho/nils-ils.md"};function S(h,a,L,p,A,D){const r=m("Mermaid");return E(),d("div",null,[a[2]||(a[2]=i('<h1 id="nils-与-ils" tabindex="-1">NILS 与 ILS <a class="header-anchor" href="#nils-与-ils" aria-label="Permalink to &quot;NILS 与 ILS&quot;">​</a></h1><div class="epigraph"><p>对比度只问亮暗差了多少；阈值处的对数斜率才问：剂量一漂，边会横着走多远。</p><footer>—— 据 Mack, Fundamental Principles of Optical Lithography 对 ILS / NILS 的定义整理</footer></div><p><a href="/litho/aerial-image-contrast">上一课</a>把 TCC 的输出命名为空中像 \\(I(x,y)\\)，并用线栅对比度 \\(C=(I_\\mathrm{max}-I_\\mathrm{min})/(I_\\mathrm{max}+I_\\mathrm{min})\\) 读调制深浅。缺口是：孤立线、孔、二维拐角没有一对全局的 \\(I_\\mathrm{max}/I_\\mathrm{min}\\)，工艺真正怕的是<strong>阈值等高线</strong>对剂量的灵敏度。本课把影像对数斜率（ILS）与归一化影像对数斜率（NILS）钉在阈值处。焦深如何沿轴毁掉这条斜率，留给<a href="/litho/depth-of-focus">焦深</a>。不要从瑞利 CD 起笔：这里还没有 \\(k_1\\)，只有空中像的局部导数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对比度 \\(C\\) 对密栅好用，对「一条边」不够。阈值模型里，边的位置满足 \\(I(x)=I_\\mathrm{th}\\)。剂量一变，\\(I\\) 整体升降（相对阈值移动），边沿 \\(x\\) 方向逃走的多少，取决于该点有多陡。缺口因此是在阈值处定义斜率，而不是再报一次 \\(C\\)。</p><p><span class="marginnote">直觉类比：ILS 就是边那个位置的「坡有多陡」。把空中像想成一座山，阈值是一条固定海拔的等高线：剂量涨一点相当于海平面涨一点，海岸线往山上退——山坡陡的地方海岸线几乎不动，平缓的滩涂则一涨水就淹出去一大片。边的 CD 误差就是这片「被淹的滩涂宽度」，所以坡陡（NILS 大）才扛得住剂量漂移。</span></p><p>上一课已经写出 NILS 的式子，当作对比度的同伴。本课要补的差是：ILS 与 NILS 不是两个名字叫同一件事，以及为什么必须取对数、必须乘上目标 CD。</p><h3 id="先-ils-再乘宽度" tabindex="-1">先 ILS，再乘宽度 <a class="header-anchor" href="#先-ils-再乘宽度" aria-label="Permalink to &quot;先 ILS，再乘宽度&quot;">​</a></h3><p>影像对数斜率</p> \\[\\mathrm{ILS}=\\frac{d\\ln I}{dx}\\Big|_{\\mathrm{th}}=\\frac{1}{I}\\frac{dI}{dx}\\Big|_{\\mathrm{th}}. \\]<p>除以 \\(I\\) 之后，整体乘一个剂量因子不改变 ILS——这正是「相对剂量误差」的自然变量。未归一的 \\(dI/dx\\) 随绝对强度标尺变，换模拟器单位就会改数。NILS 把 ILS 乘到目标线宽上：</p> \\[\\mathrm{NILS}=\\mathrm{CD}\\cdot\\mathrm{ILS}. \\]<p>不同 CD 的边可以比较：同样的相对剂量误差，NILS 大则相对 CD 误差小。</p><p><span class="marginnote">阈值必须声明：正胶常用「清掉区域的强度下限」所对应的那条等高线。换 \\(I_\\mathrm{th}\\) 等于换读斜率的位置，NILS 会变。不要和胶的 \\(\\gamma\\) 混名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在最佳焦距取垂直于边的剖线，找到 \\(I=I_\\mathrm{th}\\) 的点，算 \\(d\\ln I/dx\\)，再乘目标 CD。密栅两条边都要看；不对称照明或像差下两边 NILS 可以不同。孔类取径向最差点。Mack 把 NILS 当空中像与工艺窗口之间的桥梁：还没有完整胶模型时，先问 NILS 够不够撑住剂量轴。</p><p>对比度 \\(C\\) 与 NILS 相关但不可互换。余弦型两束成像，\\(C\\) 高通常 ILS 也高；三束加上零级偏置，\\(I_\\mathrm{min}\\) 抬高，\\(C\\) 掉，阈值若落在缓坡上，NILS 掉得更厉害。只报 \\(C=70\\%\\) 而不报阈值处斜率，会漏掉「切在哪」。</p><h3 id="剂量灵敏度的读法" tabindex="-1">剂量灵敏度的读法 <a class="header-anchor" href="#剂量灵敏度的读法" aria-label="Permalink to &quot;剂量灵敏度的读法&quot;">​</a></h3><p>相对剂量变化 \\(\\Delta E/E\\) 使相对阈值反向移动。两边对称时，相对 CD 误差与 \\(\\Delta E/E\\) 之比反比于 NILS（系数 2 来自两条边，教科书按是否用半宽会略有出入）。因此曝光宽容度与 NILS 同向变化——定量窗口是后课 E–D 的题目，本课只把光学预言钉在斜率上。</p><p><span class="marginnote">模拟器里的 ILS 有时被写成 \\(dI/dx\\) 而不取对数。对表必须看定义。Mack 的产线用语里，ILS 是对数斜率，NILS 是其无量纲化。</span></p>',20)),(E(),I(s,null,{default:t(()=>[n(r,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20I(x)%22%5D%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%20Ith%22%5D%0A%20%20TH%20--%3E%20ILS%5B%22ILS%20%3D%20d%20ln%20I%20%2F%20dx%22%5D%0A%20%20ILS%20--%3E%20NILS%5B%22NILS%20%3D%20CD%20%C2%B7%20ILS%22%5D%0A%20%20NILS%20--%3E%20EL%5B%22%E5%89%82%E9%87%8F%E8%BD%B4%E5%AE%BD%E5%AE%B9%E5%BA%A6%22%5D%0A%20%20NILS%20--%3E%20DOF%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%A6%BB%E7%84%A6%E6%8E%89%E6%96%9C%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"空中像在边附近近似一段斜坡。绝对坡度 \\(dI/dx\\) 决定「强度涨一点，边走多远」；除以当地 \\(I\\)，改成对数，对应剂量乘法。乘 CD 之后，问的是相对尺寸而不是纳米每焦耳——产线规格通常是目标 CD 的百分比。",-1)),a[5]||(a[5]=e("p",null,"低调制（零级偏置大、一级刚进瞳）让斜坡变缓，NILS 先死，剂量一漂就并线或断线。这与上一课「\\(C\\) 掉则切不出线」是同一机制的边缘版本，对孤立线和二维图形更诚实。",-1)),(E(),I(s,null,{default:t(()=>[n(r,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20DE%5B%22%E5%89%82%E9%87%8F%E6%BC%82%E7%A7%BB%20%CE%94E%2FE%22%5D%20--%3E%7C%22%E6%95%B4%E6%9D%A1%20I(x)%20%E4%B9%98%E5%9B%A0%E5%AD%90%22%7C%20UP%5B%22%E6%9B%B2%E7%BA%BF%E7%9B%B8%E5%AF%B9%E9%98%88%E5%80%BC%20Ith%20%E5%8D%87%E6%88%96%E9%99%8D%22%5D%0A%20%20UP%20--%3E%20MV%5B%22%E4%BA%A4%E7%82%B9%E6%B2%BF%20x%20%E6%A8%AA%E7%A7%BB%20%E2%89%88%20%CE%94E%2FE%20%2F%20ILS%22%5D%0A%20%20MV%20--%3E%20E1%5B%22%E5%B7%A6%E8%BE%B9%E7%BC%98%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20MV%20--%3E%20E2%5B%22%E5%8F%B3%E8%BE%B9%E7%BC%98%E5%8F%8D%E5%90%91%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20E1%20--%3E%20CD%5B%22%E7%9B%B8%E5%AF%B9%20CD%20%E8%AF%AF%E5%B7%AE%20%E2%89%88%202%C2%B7%CE%94E%2FE%20%2F%20NILS%22%5D%0A%20%20E2%20--%3E%20CD%0A%20%20CD%20--%3E%20W%7B%22NILS%20%E5%A4%A7%3F%22%7D%0A%20%20W%20--%3E%7C%22%E6%98%AF%22%7C%20SAFE%5B%22CD%20%E7%A8%B3%2C%20%E7%AA%97%E5%8F%A3%E5%AE%BD%22%5D%0A%20%20W%20--%3E%7C%22%E5%90%A6%22%7C%20BAD%5B%22%E5%B9%B6%E7%BA%BF%20%2F%20%E6%96%AD%E7%BA%BF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到空中像好不好印，密栅可报 \\(C\\)，边与窗口预言报 NILS。离焦课把 \\(\\mathrm{NILS}(z)\\) 画成峰；胶课再把光学 NILS 与扩散核相乘。不要在焦深公式里把 \\(k_2\\) 和 NILS 混成一个符号。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>NILS 是光学（加指定平面约定）的量，不含酸扩散、不含 SEM 偏置。阈值模型只是接口；真显影曲线会让「有效切点」偏离 \\(I_\\mathrm{th}\\)，预言与硅片差一截。也不存在对所有层通用的「NILS&gt;2 即可量产」：规格带、图形类别、计量噪声都会改门槛。本课不引用未公开的机台验收 NILS 表。</p><p>矢量成像改的是 \\(I\\) 本身，ILS/NILS 的定义不变。</p><p><span class="marginnote">数字实例：NILS \\(=2\\) 时，剂量多打 \\(1\\%\\)，单边横移约 \\(1\\%/2=0.5\\%\\)，两条边对称反向，相对 CD 误差约 \\(1\\%\\)；若 NILS 只有一半，同样的剂量漂移误差就翻倍。常见误区是把「NILS 大于某个数」当成万能通行证——规格门槛随图形类别、规格带和计量噪声变，孤立线和密栅的合格线并不相同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ILS 是阈值处 \\(d\\ln I/dx\\)；NILS 再乘目标 CD，便于跨尺寸比较。</li><li>对比度 \\(C\\) 读调制；NILS 读边对剂量的灵敏度。</li><li>相对 CD 误差随相对剂量误差涨、随 NILS 降。</li><li>必须声明阈值位置；ILS 不要和 \\(dI/dx\\) 混用。</li><li>离焦如何毁掉 NILS，后课。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',8))])}const c=o(B,[["render",S]]);export{N as __pageData,c as default};
